import subprocess, sys, time, signal, os, threading
def run(args, stdin_data, actions=(), env=None, cwd='/tmp/t1', total=3.0, show=True):
    p = subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env, start_new_session=True)
    p.stdin.write(stdin_data.encode()); p.stdin.close(); p.stdin=None
