#ifndef ENTR_H
#define ENTR_H

#include <limits.h>
#include <signal.h>
#include <sys/types.h>

#define RELEASE "5.7"

/* event filter types */
#define FILT_VNODE 1
#define FILT_READ  2

/* vnode event flags (kqueue compatible values) */
#define NOTE_DELETE 0x0001
#define NOTE_WRITE  0x0002
#define NOTE_EXTEND 0x0004
#define NOTE_ATTRIB 0x0008
#define NOTE_LINK   0x0010
#define NOTE_RENAME 0x0020

#define MAX_EVENTS 32

typedef struct watch_file {
	char fn[PATH_MAX];
	int wd;
	int is_dir;
	int file_count;
	mode_t mode;
} watch_file_t;

struct fs_event {
	int filter;
	int ident;
	unsigned int fflags;
	watch_file_t *file;
};

/* options */
extern int opt_aggressive;
extern int opt_clear;
extern int opt_dirwatch;
extern int opt_noninteractive;
extern int opt_postpone;
extern int opt_restart;
extern int opt_shell;
extern int opt_status;
extern int opt_oneshot;
extern int follow_symlinks;
extern int inotify_workaround;

extern watch_file_t **files;
extern int n_files;

/* notify.c */
int notify_init(void);
int notify_add(watch_file_t *file);
void notify_remove(watch_file_t *file);
void notify_keyboard(int enable);
int notify_wait(struct fs_event *list, int max, int with_timeout);

#endif
