{
	kbd_fd = enable ? STDIN_FILENO : -1;
}

static watch_file_t *
file_by_wd(int wd)
{
	int i;

	for (i = 0; i < n_files; i++)
		if (files[i]->wd == wd)
			return files[i];
	return NULL;
}

static unsigned int
convert_mask(unsigned int mask)
{
	unsigned int fflags = 0;

	if (mask & IN_DELETE_SELF)
		fflags |= NOTE_DELETE;
	if (mask & (IN_CLOSE_WRITE | IN_CREATE | IN_DELETE))
		fflags |= NOTE_WRITE;
	if (inotify_workaround && (mask & IN_MODIFY))
		fflags |= NOTE_WRITE;
	if (mask & (IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO))
		fflags |= NOTE_RENAME;
	if (mask & IN_ATTRIB)
		fflags |= NOTE_ATTRIB;
	return fflags;
}

static int
drain_inotify(struct fs_event *list, int n, int max)
{
	char buf[READ_BUF_LEN]
	    __attribute__ ((aligned(__alignof__(struct inotify_event))));
	struct inotify_event *iev;
	ssize_t len;
	ssize_t pos;
	unsigned int fflags;
	watch_file_t *file;

	do {
		len = read(ifd, buf, sizeof(buf));
	} while (len == -1 && errno == EINTR);
	if (len <= 0)
		return n;

	pos = 0;
	while (pos < len && n < max) {
		iev = (struct inotify_event *)&buf[pos];
		pos += sizeof(struct inotify_event) + iev->len;

		fflags = convert_mask(iev->mask);
		if (fflags == 0)
			continue;

		/* consecutive events on the same watch are combined */
		if (n > 0 && list[n - 1].filter == FILT_VNODE &&
		    list[n - 1].ident == iev->wd)
			fflags |= list[--n].fflags;

		file = file_by_wd(iev->wd);
		list[n].filter = FILT_VNODE;
		list[n].ident = iev->wd;
		list[n].fflags = fflags;
		list[n].file = file;
		if (file != NULL)
			n++;
	}
	return n;
