notify_wait(struct fs_event *list, int max, int with_timeout)
{
	struct pollfd pfd[2];
	int n = 0;
	int tmo;
	int rc;

	tmo = with_timeout ? SETTLE_MS : -1;
	for (;;) {
		pfd[0].fd = ifd;
		pfd[0].events = POLLIN;
		pfd[0].revents = 0;
		pfd[1].fd = kbd_fd;
		pfd[1].events = POLLIN;
		pfd[1].revents = 0;

		rc = poll(pfd, 2, tmo);
		if (rc == -1) {
			if (errno == EINTR)
				break;
			err(1, "poll");
		}
		if (rc == 0)
			break;
		if (pfd[0].revents & POLLIN)
			n = drain_inotify(list, n, max);
		if (kbd_fd != -1 &&
		    (pfd[1].revents & (POLLIN | POLLHUP | POLLERR | POLLNVAL))) {
			if (n < max) {
				list[n].filter = FILT_READ;
				list[n].ident = kbd_fd;
				list[n].fflags = 0;
				list[n].file = NULL;
				n++;
			}
			break;
		}
		tmo = SETTLE_MS;
	}
	return n;
}
