/*
 * entr - run arbitrary commands when files change
 *
 * Clean-room reimplementation written from observed behaviour.
 */
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#include <dirent.h>
#include <err.h>
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <libgen.h>
#include <pwd.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

#include "entr.h"

/* options */
int opt_aggressive;
int opt_clear;
int opt_dirwatch;
int opt_noninteractive;
int opt_postpone;
int opt_restart;
int opt_shell;
int opt_status;
int opt_oneshot;
int follow_symlinks;
int inotify_workaround;

watch_file_t **files;
int n_files;

static watch_file_t *leading_edge;
static int restart_signal = SIGTERM;
static int open_max;

static volatile pid_t child_pid;
static volatile pid_t status_pid;
static int status_fd = -1;
static volatile sig_atomic_t terminating;

static int tty_saved;
static struct termios canonical_tty;
static struct termios raw_tty;
static int kbd_enabled;

static const char example_status_script[] =
    "# http://eradman.com/entrproject/status-filters.html\n"
    "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
    "/^exit/ { print $3, \"returned exit code\", $2; }\n";

static void handle_exit(int sig);

/* helpers */

static void
sleep_ms(long ms)
{
	struct timespec ts, rem;

	ts.tv_sec = ms / 1000;
	ts.tv_nsec = (ms % 1000) * 1000000L;
	while (nanosleep(&ts, &rem) == -1 && errno == EINTR)
		ts = rem;
}

static int
xstat(const char *path, struct stat *sb)
{
	if (follow_symlinks)
		return stat(path, sb);
	return lstat(path, sb);
}

static int
exit_code(int status)
{
	if (WIFSIGNALED(status))
		return 128 + WTERMSIG(status);
	return WEXITSTATUS(status);
}

static void
usage(int full)
{
	fprintf(stderr, "release: %s\n", RELEASE);
	fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] "
	    "< filenames\n");
	if (full) {
		printf("summary:\n"
		    "    -a  Do not consolidate events\n"
		    "    -c  Clear screen before execution\n"
		    "    -d  Track files added or removed from directories\n"
		    "    -n  Non-interactive mode\n"
		    "    -p  Wait for first event\n"
		    "    -r  Run as a background process, use signal to restart\n"
		    "    -s  Evaluate using a shell\n"
		    "    -x  Format exit status\n"
		    "    -z  Exit after the utility completes\n"
		    "docs:\n"
		    "    man entr\n");
	} else {
		fprintf(stderr, "hint: use -h to display option summary\n");
	}
	exit(1);
}

/* terminal handling */

static void
tty_restore(void)
{
	if (tty_saved)
		(void)tcsetattr(STDIN_FILENO, TCSADRAIN, &canonical_tty);
}

static void
tty_raw(void)
{
	if (tty_saved)
		(void)tcsetattr(STDIN_FILENO, TCSADRAIN, &raw_tty);
}

static void
tty_setup(void)
{
	int fd;

	fd = open("/dev/tty", O_RDONLY);
	if (fd > STDIN_FILENO) {
		if (dup2(fd, STDIN_FILENO) == -1)
			warn("can't dup2 to stdin");
		close(fd);
	}
	if (tcgetattr(STDIN_FILENO, &canonical_tty) < 0)
		errx(1, "unable to get terminal attributes, use '-n' to run "
		    "non-interactively");
	raw_tty = canonical_tty;
	raw_tty.c_lflag &= ~(ICANON | ECHO);
	tty_saved = 1;
	kbd_enabled = 1;
	notify_keyboard(1);
}

/* child process management */

static void
block_chld(sigset_t *old)
{
	sigset_t set;

	sigemptyset(&set);
	sigaddset(&set, SIGCHLD);
	sigprocmask(SIG_BLOCK, &set, old);
}

static void
terminate_utility(void)
{
	sigset_t old;
	int status;
	pid_t pid;

	if (!opt_restart || child_pid <= 0)
		return;
	block_chld(&old);
	pid = child_pid;
	terminating = 1;
	(void)killpg(pid, restart_signal);
	while (waitpid(pid, &status, 0) == -1 && errno == EINTR)
		;
	child_pid = 0;
	terminating = 0;
	sigprocmask(SIG_SETMASK, &old, NULL);
}

static void
cleanup(void)
{
	tty_restore();
	terminate_utility();
}

static void
handle_exit(int sig)
{
	struct sigaction sa;
	sigset_t set;
	int status;
	pid_t pid;

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = SIG_DFL;
	sigemptyset(&sa.sa_mask);
	sigaction(sig, &sa, NULL);

	tty_restore();
	if (opt_restart) {
		terminate_utility();
	} else if ((pid = child_pid) > 0) {
		while (waitpid(pid, &status, 0) == -1 && errno == EINTR)
			;
		child_pid = 0;
	}
	if (status_pid > 0)
		(void)kill(status_pid, SIGKILL);

	if (sig == SIGINT || sig == SIGHUP)
		exit(0);

	tty_saved = 0;
	sigemptyset(&set);
	sigaddset(&set, sig);
	sigprocmask(SIG_UNBLOCK, &set, NULL);
	raise(sig);
	_exit(128 + sig);
}

static void
handle_chld(int sig)
{
	int saved_errno = errno;
	int status;
	pid_t pid;

	(void)sig;
	if (status_pid > 0) {
		pid = waitpid(status_pid, &status, WNOHANG);
		if (pid == status_pid) {
			status_pid = 0;
			warnx("status process terminated");
			handle_exit(SIGINT);
		}
	}
	if (opt_restart && child_pid > 0 && !terminating) {
		pid = waitpid(child_pid, &status, WNOHANG);
		if (pid == child_pid && opt_oneshot)
			exit(exit_code(status));
	}
	errno = saved_errno;
}

static void
install_handlers(void)
{
	struct sigaction sa;

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = handle_exit;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) != 0)
		err(1, "Failed to set SIGINT handler");
	if (sigaction(SIGTERM, &sa, NULL) != 0)
		err(1, "Failed to set SIGTERM handler");
	if (sigaction(SIGHUP, &sa, NULL) != 0)
		err(1, "Failed to set SIGHUP handler");

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = handle_chld;
	sigemptyset(&sa.sa_mask);
	sigaddset(&sa.sa_mask, SIGINT);
	sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
	if (sigaction(SIGCHLD, &sa, NULL) != 0)
		err(1, "Failed to set SIGCHLD handler");
}

/* status filter */

static void
start_status_filter(void)
{
	static char default_path[PATH_MAX];
	char dir[PATH_MAX];
	const char *path;
	struct passwd *pw;
	struct stat sb;
	char *args[7];
	int fds[2];
	int fd;
	int i;
	pid_t pid;

	path = getenv("ENTR_STATUS_SCRIPT");
	if (path == NULL || *path == '\0') {
		pw = getpwuid(getuid());
		if (pw == NULL)
			errx(1, "unable to determine home directory");
		snprintf(default_path, sizeof(default_path),
		    "%s/.entr/status.awk", pw->pw_dir);
		path = default_path;
	}

	if (stat(path, &sb) != 0) {
		strncpy(dir, path, sizeof(dir) - 1);
		dir[sizeof(dir) - 1] = '\0';
		(void)mkdir(dirname(dir), 0750);
		printf("entr: created '%s'\n", path);
		fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
		if (fd == -1)
			err(1, "open");
		if (write(fd, example_status_script,
		    sizeof(example_status_script) - 1) == -1)
			err(1, "write");
		close(fd);
	}

	if (pipe(fds) == -1)
		err(1, "pipe");

	i = 0;
	args[i++] = "awk";
	args[i++] = "-F";
	args[i++] = "|";
	args[i++] = "-f";
	args[i++] = (char *)path;
	if (opt_status < 2)
		args[i++] = "-S";
	args[i] = NULL;

	pid = fork();
	if (pid == -1)
		err(1, "can't fork status process");
	if (pid == 0) {
		if (dup2(fds[0], STDIN_FILENO) == -1)
			err(1, "dup2");
		close(fds[1]);
		execvp(args[0], args);
		err(1, "could not exec /usr/bin/awk");
	}
	close(fds[0]);
	status_fd = fds[1];
	status_pid = pid;
}

static void
report_status(const char *name, int status)
{
	char line[PATH_MAX + 64];
	char base[PATH_MAX];
	int len;

	if (status_fd == -1)
		return;
	strncpy(base, name, sizeof(base) - 1);
	base[sizeof(base) - 1] = '\0';
	if (WIFSIGNALED(status))
		len = snprintf(line, sizeof(line), "signal|%d|%s\n",
		    WTERMSIG(status), basename(base));
	else
		len = snprintf(line, sizeof(line), "exit|%d|%s\n",
		    WEXITSTATUS(status), basename(base));
	if (len > 0)
		(void)write(status_fd, line, (size_t)len);
}

