		args = calloc(argc + 1, sizeof(char *));
		if (args == NULL)
			err(1, "calloc");
		replaced = 0;
		for (i = 0; i < argc; i++) {
			if (!replaced && strcmp(argv[i], "/_") == 0) {
				args[i] = leading_edge->fn;
				replaced = 1;
			} else
