		err(1, "exec %s", arg0);
	}
	child_pid = pid;

	if (!opt_restart) {
		while (waitpid(pid, &status, 0) == -1) {
			if (errno != EINTR) {
				status = 0;
				break;
			}
		}
		child_pid = 0;
		report_status(arg0, status);
	}
	free(args);
	return status;
}

/* input processing */

static int
list_dir(const char *path)
{
	struct dirent *de;
	DIR *d;
	int count = 0;

	d = opendir(path);
	if (d == NULL)
		errx(1, "unable to open directory: '%s'", path);
	while ((de = readdir(d)) != NULL) {
		if (opt_dirwatch < 2 && de->d_name[0] == '.')
			continue;
		count++;
	}
	closedir(d);
	return count;
}

static int
compare_dir_contents(watch_file_t *file)
{
	if (file->file_count != list_dir(file->fn)) {
		/* give the directory a moment to settle */
		sleep_ms(500);
		return 1;
	}
	return 0;
}

static watch_file_t *
add_entry(const char *path, int is_dir, mode_t mode)
{
	static int cap;
	watch_file_t *f;

	if (n_files + 1 > cap) {
		cap = cap ? cap * 2 : 64;
		files = realloc(files, sizeof(watch_file_t *) * (size_t)cap);
		if (files == NULL)
			err(1, "realloc");
	}
	f = calloc(1, sizeof(watch_file_t));
	if (f == NULL)
		err(1, "calloc");
	strncpy(f->fn, path, sizeof(f->fn) - 1);
	f->wd = -1;
	f->is_dir = is_dir;
	f->mode = mode;
	if (is_dir)
		f->file_count = list_dir(f->fn);
	files[n_files++] = f;
	return f;
}

static int
process_input(FILE *input, int max_files)
{
	char buf[PATH_MAX];
	char tmp[PATH_MAX];
	struct stat sb;
	struct stat dsb;
	char *p;
	char *path;
	int i;
	int matches;

	while (fgets(buf, sizeof(buf), input) != NULL) {
		if ((p = strchr(buf, '\n')) != NULL)
			*p = '\0';
		if (buf[0] == '\0')
			continue;

		if (xstat(buf, &sb) == -1) {
			warnx("unable to stat '%s'", buf);
			continue;
		}
		if (S_ISREG(sb.st_mode) || S_ISDIR(sb.st_mode) ||
		    S_ISLNK(sb.st_mode))
			add_entry(buf, S_ISDIR(sb.st_mode) ? 1 : 0,
			    sb.st_mode);
		else
			continue;

		if (opt_dirwatch > 0) {
			if (S_ISDIR(sb.st_mode)) {
				path = buf;
			} else {
				strncpy(tmp, buf, sizeof(tmp) - 1);
				tmp[sizeof(tmp) - 1] = '\0';
				path = dirname(tmp);
			}
			matches = 0;
			for (i = 0; i < n_files; i++)
				if (strcmp(files[i]->fn, path) == 0)
					matches++;
			if (matches == 0) {
				if (stat(path, &dsb) == -1)
					dsb.st_mode = S_IFDIR | 0755;
				add_entry(path, 1, dsb.st_mode);
			}
		}
		if (n_files + 1 > max_files)
			return -1;
	}
	return n_files;
}

static void
watch_file(watch_file_t *file)
{
	struct stat sb;
	int saved_errno = ENOENT;
	int i;

	for (i = 0; i < 10; i++) {
		if (xstat(file->fn, &sb) == 0)
			break;
		saved_errno = errno;
		sleep_ms(100);
	}
	if (i == 10) {
		errno = saved_errno;
		err(1, "cannot open '%s'", file->fn);
	}
	if (notify_add(file) == -1)
		err(1, "failed to register VNODE event");
}

static int
read_open_max(void)
{
	FILE *fp;
	int value = 0;

	fp = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
	if (fp != NULL) {
		if (fscanf(fp, "%d", &value) != 1)
			value = 0;
		fclose(fp);
	}
	if (value <= 0)
		value = 65536;
	return value;
}

static void
parse_restart_signal(void)
{
	const char *s;

	s = getenv("ENTR_RESTART_SIGNAL");
	if (s == NULL)
		return;
	if (strncmp(s, "SIG", 3) == 0)
		s += 3;
	if (strcmp(s, "HUP") == 0)
		restart_signal = SIGHUP;
	else if (strcmp(s, "INT") == 0)
		restart_signal = SIGINT;
	else if (strcmp(s, "QUIT") == 0)
		restart_signal = SIGQUIT;
	else
		errx(1, "unrecognized signal: %s <> (HUP, INT, QUIT, TERM, "
		    "USR1, USR2)", s);
}

/* main loop */

static void
watch_loop(char **argv)
{
	struct fs_event evs[MAX_EVENTS];
	struct stat sb;
	watch_file_t *file;
	unsigned int ff;
	int nev;
	int i;
	int reopen_only = 0;
	int collate_only = 0;
	int do_exec = 0;
	int dir_modified = 0;
	int leading_edge_set = 0;
	int mode_changed;
	int status;
	char c;

	leading_edge = files[0];
	if (!opt_postpone) {
		status = run_utility(argv);
		if (opt_oneshot && !opt_restart)
			exit(exit_code(status));
		if (!opt_aggressive)
			reopen_only = 1;
	}

	for (;;) {
		tty_raw();
		if (reopen_only || collate_only) {
			nev = notify_wait(evs, MAX_EVENTS, 1);
		} else {
			nev = notify_wait(evs, MAX_EVENTS, 0);
			dir_modified = 0;
		}

		/* keyboard commands */
		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_READ)
				continue;
			if (read(STDIN_FILENO, &c, 1) < 1) {
				kbd_enabled = 0;
				notify_keyboard(0);
				continue;
			}
			if (c == ' ')
				do_exec = 1;
			else if (c == 'q')
				handle_exit(SIGINT);
		}

		/* directory changes and replaced files */
		collate_only = 0;
		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_VNODE)
				continue;
			file = evs[i].file;
			if (file->is_dir)
				dir_modified += compare_dir_contents(file);
			if (evs[i].fflags & (NOTE_DELETE | NOTE_RENAME)) {
				notify_remove(file);
				watch_file(file);
				collate_only = 1;
			}
		}

		if (reopen_only) {
			reopen_only = 0;
			continue;
		}

		if (dir_modified > 0 && opt_restart) {
			terminate_utility();
			errx(2, "directory altered");
		}

		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_VNODE)
				continue;
			file = evs[i].file;
			ff = evs[i].fflags;
			mode_changed = 0;
			if (file->is_dir && dir_modified == 0)
				continue;
			if (ff & NOTE_ATTRIB) {
				if (file->is_dir)
					continue;
				if (xstat(file->fn, &sb) != 0)
					continue;
				if (sb.st_mode != file->mode)
					mode_changed = 1;
				file->mode = sb.st_mode;
			}
			if (getenv("EV_TRACE") != NULL &&
			    (file->is_dir || S_ISREG(file->mode)))
				fprintf(stderr, "%d/%d: fflags: 0x%x %s %o %s\n",
				    i, nev, ff, file->is_dir ? "d" : "r",
				    (unsigned int)file->mode, file->fn);
			if ((ff & (NOTE_DELETE | NOTE_WRITE | NOTE_RENAME)) ||
			    mode_changed) {
				if (!file->is_dir && S_ISREG(file->mode) &&
				    !leading_edge_set) {
					leading_edge = file;
					leading_edge_set = 1;
				}
				do_exec = 1;
			}
		}

		if (collate_only)
			continue;

		if (dir_modified > 0) {
			run_utility(argv);
			errx(2, "directory altered");
		}

		if (do_exec) {
			do_exec = 0;
			leading_edge_set = 0;
			status = run_utility(argv);
			if (opt_oneshot && !opt_restart)
				exit(exit_code(status));
			if (!opt_aggressive)
				reopen_only = 1;
		}
	}
}

int
main(int argc, char *argv[])
{
	int ch;
	int i;
	int n;

	if (argc < 2)
		usage(0);
	if (strcmp(argv[1], "-h") == 0)
		usage(1);

	while ((ch = getopt(argc, argv, "+acdnprsxz")) != -1) {
		switch (ch) {
		case 'a':
			opt_aggressive = 1;
			break;
		case 'c':
			opt_clear++;
			break;
		case 'd':
			opt_dirwatch++;
			break;
		case 'n':
			opt_noninteractive = 1;
			break;
		case 'p':
			opt_postpone = 1;
			break;
		case 'r':
			opt_restart = 1;
			break;
		case 's':
			opt_shell = 1;
			break;
		case 'x':
			opt_status++;
			break;
		case 'z':
			opt_oneshot = 1;
			break;
		default:
			usage(0);
		}
	}
	argc -= optind;
	argv += optind;
	if (argc < 1)
		usage(0);

	if (opt_restart && opt_status)
		errx(1, "-r and -x may not be combined");
	if (opt_shell && argc > 1)
		errx(1, "-s requires commands to be formatted as a single "
		    "argument");

	parse_restart_signal();

	/* prevent interactive utilities from paging output */
	setenv("PAGER", "/bin/cat", 0);

	follow_symlinks = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
	inotify_workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;

	open_max = read_open_max();
	if (getenv("EV_TRACE") != NULL)
		fprintf(stderr, "open_max: %d\n", open_max);

	install_handlers();

	if (opt_status)
		start_status_filter();

	notify_init();

	if (inotify_workaround)
		warnx("broken inotify workaround enabled");

	if (isatty(STDIN_FILENO))
		usage(0);

	atexit(cleanup);

	n = process_input(stdin, open_max);
	if (n == 0)
		errx(1, "No regular files to watch");
	if (n == -1)
		errx(1, "Too many files listed; the hard limit for your login "
		    "class is %d. Please consult "
		    "http://eradman.com/entrproject/limits.html", open_max);

	for (i = 0; i < n_files; i++)
		watch_file(files[i]);

	if (!opt_noninteractive)
		tty_setup();

	watch_loop(argv);
	return 0;
}
EOF
cd /workspace && gcc -O2 -Wall -Wextra -o /tmp/myentr src/entr.c src/notify.c 2>&1 | head -30"}

actions.command:
cat > /workspace/src/entr.c <<'EOF'
/*
 * entr - run arbitrary commands when files change
 *
 * Clean-room reimplementation written from observed behaviour.
 */
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#include <dirent.h>
#include <err.h>
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <libgen.h>
#include <pwd.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

#include "entr.h"

/* options */
int opt_aggressive;
int opt_clear;
int opt_dirwatch;
int opt_noninteractive;
int opt_postpone;
int opt_restart;
int opt_shell;
int opt_status;
int opt_oneshot;
int follow_symlinks;
int inotify_workaround;

watch_file_t **files;
int n_files;

static watch_file_t *leading_edge;
static int restart_signal = SIGTERM;
static int open_max;

static volatile pid_t child_pid;
static volatile pid_t status_pid;
static int status_fd = -1;
static volatile sig_atomic_t terminating;

static int tty_saved;
static struct termios canonical_tty;
static struct termios raw_tty;
static int kbd_enabled;

static const char example_status_script[] =
    "# http://eradman.com/entrproject/status-filters.html\n"
    "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
    "/^exit/ { print $3, \"returned exit code\", $2; }\n";

static void handle_exit(int sig);

/* helpers */

static void
sleep_ms(long ms)
{
	struct timespec ts, rem;

	ts.tv_sec = ms / 1000;
	ts.tv_nsec = (ms % 1000) * 1000000L;
	while (nanosleep(&ts, &rem) == -1 && errno == EINTR)
		ts = rem;
}

static int
xstat(const char *path, struct stat *sb)
{
	if (follow_symlinks)
		return stat(path, sb);
	return lstat(path, sb);
}

static int
exit_code(int status)
{
	if (WIFSIGNALED(status))
		return 128 + WTERMSIG(status);
	return WEXITSTATUS(status);
}

static void
usage(int full)
{
	fprintf(stderr, "release: %s\n", RELEASE);
	fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] "
	    "< filenames\n");
	if (full) {
		printf("summary:\n"
		    "    -a  Do not consolidate events\n"
		    "    -c  Clear screen before execution\n"
		    "    -d  Track files added or removed from directories\n"
		    "    -n  Non-interactive mode\n"
		    "    -p  Wait for first event\n"
		    "    -r  Run as a background process, use signal to restart\n"
		    "    -s  Evaluate using a shell\n"
		    "    -x  Format exit status\n"
		    "    -z  Exit after the utility completes\n"
		    "docs:\n"
		    "    man entr\n");
	} else {
		fprintf(stderr, "hint: use -h to display option summary\n");
	}
	exit(1);
}

/* terminal handling */

static void
tty_restore(void)
{
	if (tty_saved)
		(void)tcsetattr(STDIN_FILENO, TCSADRAIN, &canonical_tty);
}

static void
tty_raw(void)
{
	if (tty_saved)
		(void)tcsetattr(STDIN_FILENO, TCSADRAIN, &raw_tty);
}

static void
tty_setup(void)
{
	int fd;

	fd = open("/dev/tty", O_RDONLY);
	if (fd > STDIN_FILENO) {
		if (dup2(fd, STDIN_FILENO) == -1)
			warn("can't dup2 to stdin");
		close(fd);
	}
	if (tcgetattr(STDIN_FILENO, &canonical_tty) < 0)
		errx(1, "unable to get terminal attributes, use '-n' to run "
		    "non-interactively");
	raw_tty = canonical_tty;
	raw_tty.c_lflag &= ~(ICANON | ECHO);
	tty_saved = 1;
	kbd_enabled = 1;
	notify_keyboard(1);
}

/* child process management */

static void
block_chld(sigset_t *old)
{
	sigset_t set;

	sigemptyset(&set);
	sigaddset(&set, SIGCHLD);
	sigprocmask(SIG_BLOCK, &set, old);
}

static void
terminate_utility(void)
{
	sigset_t old;
	int status;
	pid_t pid;

	if (!opt_restart || child_pid <= 0)
		return;
	block_chld(&old);
	pid = child_pid;
	terminating = 1;
	(void)killpg(pid, restart_signal);
	while (waitpid(pid, &status, 0) == -1 && errno == EINTR)
		;
	child_pid = 0;
	terminating = 0;
	sigprocmask(SIG_SETMASK, &old, NULL);
}

static void
cleanup(void)
{
	tty_restore();
	terminate_utility();
}

static void
handle_exit(int sig)
{
	struct sigaction sa;
	sigset_t set;
	int status;
	pid_t pid;

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = SIG_DFL;
	sigemptyset(&sa.sa_mask);
	sigaction(sig, &sa, NULL);

	tty_restore();
	if (opt_restart) {
		terminate_utility();
	} else if ((pid = child_pid) > 0) {
		while (waitpid(pid, &status, 0) == -1 && errno == EINTR)
			;
		child_pid = 0;
	}
	if (status_pid > 0)
		(void)kill(status_pid, SIGKILL);

	if (sig == SIGINT || sig == SIGHUP)
		exit(0);

	tty_saved = 0;
	sigemptyset(&set);
	sigaddset(&set, sig);
	sigprocmask(SIG_UNBLOCK, &set, NULL);
	raise(sig);
	_exit(128 + sig);
}

static void
handle_chld(int sig)
{
	int saved_errno = errno;
	int status;
	pid_t pid;

	(void)sig;
	if (status_pid > 0) {
		pid = waitpid(status_pid, &status, WNOHANG);
		if (pid == status_pid) {
			status_pid = 0;
			warnx("status process terminated");
			handle_exit(SIGINT);
		}
	}
	if (opt_restart && child_pid > 0 && !terminating) {
		pid = waitpid(child_pid, &status, WNOHANG);
		if (pid == child_pid && opt_oneshot)
			exit(exit_code(status));
	}
	errno = saved_errno;
}

static void
install_handlers(void)
{
	struct sigaction sa;

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = handle_exit;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) != 0)
		err(1, "Failed to set SIGINT handler");
	if (sigaction(SIGTERM, &sa, NULL) != 0)
		err(1, "Failed to set SIGTERM handler");
	if (sigaction(SIGHUP, &sa, NULL) != 0)
		err(1, "Failed to set SIGHUP handler");

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = handle_chld;
	sigemptyset(&sa.sa_mask);
	sigaddset(&sa.sa_mask, SIGINT);
	sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
	if (sigaction(SIGCHLD, &sa, NULL) != 0)
		err(1, "Failed to set SIGCHLD handler");
}

/* status filter */

static void
start_status_filter(void)
{
	static char default_path[PATH_MAX];
	char dir[PATH_MAX];
	const char *path;
	struct passwd *pw;
	struct stat sb;
	char *args[7];
	int fds[2];
	int fd;
	int i;
	pid_t pid;

	path = getenv("ENTR_STATUS_SCRIPT");
	if (path == NULL || *path == '\0') {
		pw = getpwuid(getuid());
		if (pw == NULL)
			errx(1, "unable to determine home directory");
		snprintf(default_path, sizeof(default_path),
		    "%s/.entr/status.awk", pw->pw_dir);
		path = default_path;
	}

	if (stat(path, &sb) != 0) {
		strncpy(dir, path, sizeof(dir) - 1);
		dir[sizeof(dir) - 1] = '\0';
		(void)mkdir(dirname(dir), 0750);
		printf("entr: created '%s'\n", path);
		fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
		if (fd == -1)
			err(1, "open");
		if (write(fd, example_status_script,
		    sizeof(example_status_script) - 1) == -1)
			err(1, "write");
		close(fd);
	}

	if (pipe(fds) == -1)
		err(1, "pipe");

	i = 0;
	args[i++] = "awk";
	args[i++] = "-F";
	args[i++] = "|";
	args[i++] = "-f";
	args[i++] = (char *)path;
	if (opt_status < 2)
		args[i++] = "-S";
	args[i] = NULL;

	pid = fork();
	if (pid == -1)
		err(1, "can't fork status process");
	if (pid == 0) {
		if (dup2(fds[0], STDIN_FILENO) == -1)
			err(1, "dup2");
		close(fds[1]);
		execvp(args[0], args);
		err(1, "could not exec /usr/bin/awk");
	}
	close(fds[0]);
	status_fd = fds[1];
	status_pid = pid;
}

static void
report_status(const char *name, int status)
{
	char line[PATH_MAX + 64];
	char base[PATH_MAX];
	int len;

	if (status_fd == -1)
		return;
	strncpy(base, name, sizeof(base) - 1);
	base[sizeof(base) - 1] = '\0';
	if (WIFSIGNALED(status))
		len = snprintf(line, sizeof(line), "signal|%d|%s\n",
		    WTERMSIG(status), basename(base));
	else
		len = snprintf(line, sizeof(line), "exit|%d|%s\n",
		    WEXITSTATUS(status), basename(base));
	if (len > 0)
		(void)write(status_fd, line, (size_t)len);
}

/* running the utility */

static int
run_utility(char **argv)
{
	char **args;
	char *arg0;
	int argc;
	int i;
	int replaced;
	int status = 0;
	pid_t pid;
	int fd;

	for (argc = 0; argv[argc] != NULL; argc++)
		;

	if (opt_shell) {
		args = calloc(5, sizeof(char *));
		if (args == NULL)
			err(1, "calloc");
		arg0 = getenv("SHELL");
		if (arg0 == NULL)
			arg0 = "/bin/sh";
		args[0] = arg0;
		args[1] = "-c";
		args[2] = argv[0];
		args[3] = leading_edge->fn;
		args[4] = NULL;
	} else {
		args = calloc(argc + 1, sizeof(char *));
		if (args == NULL)
			err(1, "calloc");
		replaced = 0;
		for (i = 0; i < argc; i++) {
			if (!replaced && strcmp(argv[i], "/_") == 0) {
				args[i] = leading_edge->fn;
				replaced = 1;
			} else
				args[i] = argv[i];
		}
		args[argc] = NULL;
		arg0 = args[0];
	}

	tty_restore();
	terminate_utility();

	if (opt_clear == 1)
		printf("\033[2J\033[H");
	else if (opt_clear > 1)
		printf("\033[2J\033[3J\033[H");
	fflush(stdout);

	pid = fork();
	if (pid == -1)
		err(1, "can't fork process");
	if (pid == 0) {
		if (opt_restart) {
			setpgid(0, 0);
			fd = open("/dev/null", O_RDONLY);
			if (fd != -1) {
				dup2(fd, STDIN_FILENO);
				if (fd != STDIN_FILENO)
					close(fd);
			}
		}
		execvp(arg0, args);
		err(1, "exec %s", arg0);
	}
	child_pid = pid;

	if (!opt_restart) {
		while (waitpid(pid, &status, 0) == -1) {
			if (errno != EINTR) {
				status = 0;
				break;
			}
		}
		child_pid = 0;
		report_status(arg0, status);
	}
	free(args);
	return status;
}

/* input processing */

static int
list_dir(const char *path)
{
	struct dirent *de;
	DIR *d;
	int count = 0;

	d = opendir(path);
	if (d == NULL)
		errx(1, "unable to open directory: '%s'", path);
	while ((de = readdir(d)) != NULL) {
		if (opt_dirwatch < 2 && de->d_name[0] == '.')
			continue;
		count++;
	}
	closedir(d);
	return count;
}

static int
compare_dir_contents(watch_file_t *file)
{
	if (file->file_count != list_dir(file->fn)) {
		/* give the directory a moment to settle */
		sleep_ms(500);
		return 1;
	}
	return 0;
}

static watch_file_t *
add_entry(const char *path, int is_dir, mode_t mode)
{
	static int cap;
	watch_file_t *f;

	if (n_files + 1 > cap) {
		cap = cap ? cap * 2 : 64;
		files = realloc(files, sizeof(watch_file_t *) * (size_t)cap);
		if (files == NULL)
			err(1, "realloc");
	}
	f = calloc(1, sizeof(watch_file_t));
	if (f == NULL)
		err(1, "calloc");
	strncpy(f->fn, path, sizeof(f->fn) - 1);
	f->wd = -1;
	f->is_dir = is_dir;
	f->mode = mode;
	if (is_dir)
		f->file_count = list_dir(f->fn);
	files[n_files++] = f;
	return f;
}

static int
process_input(FILE *input, int max_files)
{
	char buf[PATH_MAX];
	char tmp[PATH_MAX];
	struct stat sb;
	struct stat dsb;
	char *p;
	char *path;
	int i;
	int matches;

	while (fgets(buf, sizeof(buf), input) != NULL) {
		if ((p = strchr(buf, '\n')) != NULL)
			*p = '\0';
		if (buf[0] == '\0')
			continue;

		if (xstat(buf, &sb) == -1) {
			warnx("unable to stat '%s'", buf);
			continue;
		}
		if (S_ISREG(sb.st_mode) || S_ISDIR(sb.st_mode) ||
		    S_ISLNK(sb.st_mode))
			add_entry(buf, S_ISDIR(sb.st_mode) ? 1 : 0,
			    sb.st_mode);
		else
			continue;

		if (opt_dirwatch > 0) {
			if (S_ISDIR(sb.st_mode)) {
				path = buf;
			} else {
				strncpy(tmp, buf, sizeof(tmp) - 1);
				tmp[sizeof(tmp) - 1] = '\0';
				path = dirname(tmp);
			}
			matches = 0;
			for (i = 0; i < n_files; i++)
				if (strcmp(files[i]->fn, path) == 0)
					matches++;
			if (matches == 0) {
				if (stat(path, &dsb) == -1)
					dsb.st_mode = S_IFDIR | 0755;
				add_entry(path, 1, dsb.st_mode);
			}
		}
		if (n_files + 1 > max_files)
			return -1;
	}
	return n_files;
}

static void
watch_file(watch_file_t *file)
{
	struct stat sb;
	int saved_errno = ENOENT;
	int i;

	for (i = 0; i < 10; i++) {
		if (xstat(file->fn, &sb) == 0)
			break;
		saved_errno = errno;
		sleep_ms(100);
	}
	if (i == 10) {
		errno = saved_errno;
		err(1, "cannot open '%s'", file->fn);
	}
	if (notify_add(file) == -1)
		err(1, "failed to register VNODE event");
}

static int
read_open_max(void)
{
	FILE *fp;
	int value = 0;

	fp = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
	if (fp != NULL) {
		if (fscanf(fp, "%d", &value) != 1)
			value = 0;
		fclose(fp);
	}
	if (value <= 0)
		value = 65536;
	return value;
}

static void
parse_restart_signal(void)
{
	const char *s;

	s = getenv("ENTR_RESTART_SIGNAL");
	if (s == NULL)
		return;
	if (strncmp(s, "SIG", 3) == 0)
		s += 3;
	if (strcmp(s, "HUP") == 0)
		restart_signal = SIGHUP;
	else if (strcmp(s, "INT") == 0)
		restart_signal = SIGINT;
	else if (strcmp(s, "QUIT") == 0)
		restart_signal = SIGQUIT;
	else
		errx(1, "unrecognized signal: %s <> (HUP, INT, QUIT, TERM, "
		    "USR1, USR2)", s);
}

/* main loop */

static void
watch_loop(char **argv)
{
	struct fs_event evs[MAX_EVENTS];
	struct stat sb;
	watch_file_t *file;
	unsigned int ff;
	int nev;
	int i;
	int reopen_only = 0;
	int collate_only = 0;
	int do_exec = 0;
	int dir_modified = 0;
	int leading_edge_set = 0;
	int mode_changed;
	int status;
	char c;

	leading_edge = files[0];
	if (!opt_postpone) {
		status = run_utility(argv);
		if (opt_oneshot && !opt_restart)
			exit(exit_code(status));
		if (!opt_aggressive)
			reopen_only = 1;
	}

	for (;;) {
		tty_raw();
		if (reopen_only || collate_only) {
			nev = notify_wait(evs, MAX_EVENTS, 1);
		} else {
			nev = notify_wait(evs, MAX_EVENTS, 0);
			dir_modified = 0;
		}

		/* keyboard commands */
		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_READ)
				continue;
			if (read(STDIN_FILENO, &c, 1) < 1) {
				kbd_enabled = 0;
				notify_keyboard(0);
				continue;
			}
			if (c == ' ')
				do_exec = 1;
			else if (c == 'q')
				handle_exit(SIGINT);
		}

		/* directory changes and replaced files */
		collate_only = 0;
		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_VNODE)
				continue;
			file = evs[i].file;
			if (file->is_dir)
				dir_modified += compare_dir_contents(file);
			if (evs[i].fflags & (NOTE_DELETE | NOTE_RENAME)) {
				notify_remove(file);
				watch_file(file);
				collate_only = 1;
			}
		}

		if (reopen_only) {
			reopen_only = 0;
			continue;
		}

		if (dir_modified > 0 && opt_restart) {
			terminate_utility();
			errx(2, "directory altered");
		}

		for (i = 0; i < nev; i++) {
			if (evs[i].filter != FILT_VNODE)
				continue;
			file = evs[i].file;
			ff = evs[i].fflags;
			mode_changed = 0;
			if (file->is_dir && dir_modified == 0)
				continue;
			if (ff & NOTE_ATTRIB) {
				if (file->is_dir)
					continue;
				if (xstat(file->fn, &sb) != 0)
					continue;
				if (sb.st_mode != file->mode)
					mode_changed = 1;
				file->mode = sb.st_mode;
			}
			if (getenv("EV_TRACE") != NULL &&
			    (file->is_dir || S_ISREG(file->mode)))
				fprintf(stderr, "%d/%d: fflags: 0x%x %s %o %s\n",
				    i, nev, ff, file->is_dir ? "d" : "r",
				    (unsigned int)file->mode, file->fn);
			if ((ff & (NOTE_DELETE | NOTE_WRITE | NOTE_RENAME)) ||
			    mode_changed) {
				if (!file->is_dir && S_ISREG(file->mode) &&
				    !leading_edge_set) {
					leading_edge = file;
					leading_edge_set = 1;
				}
				do_exec = 1;
			}
		}

		if (collate_only)
			continue;

		if (dir_modified > 0) {
			run_utility(argv);
			errx(2, "directory altered");
		}

		if (do_exec) {
			do_exec = 0;
			leading_edge_set = 0;
			status = run_utility(argv);
			if (opt_oneshot && !opt_restart)
				exit(exit_code(status));
			if (!opt_aggressive)
				reopen_only = 1;
		}
	}
}

int
main(int argc, char *argv[])
{
	int ch;
	int i;
	int n;

	if (argc < 2)
		usage(0);
	if (strcmp(argv[1], "-h") == 0)
		usage(1);

	while ((ch = getopt(argc, argv, "+acdnprsxz")) != -1) {
		switch (ch) {
		case 'a':
			opt_aggressive = 1;
			break;
		case 'c':
			opt_clear++;
			break;
		case 'd':
			opt_dirwatch++;
			break;
		case 'n':
			opt_noninteractive = 1;
			break;
		case 'p':
			opt_postpone = 1;
			break;
		case 'r':
			opt_restart = 1;
			break;
		case 's':
			opt_shell = 1;
			break;
		case 'x':
			opt_status++;
			break;
		case 'z':
			opt_oneshot = 1;
			break;
		default:
			usage(0);
		}
	}
	argc -= optind;
	argv += optind;
	if (argc < 1)
		usage(0);

	if (opt_restart && opt_status)
		errx(1, "-r and -x may not be combined");
	if (opt_shell && argc > 1)
		errx(1, "-s requires commands to be formatted as a single "
		    "argument");

	parse_restart_signal();

	/* prevent interactive utilities from paging output */
	setenv("PAGER", "/bin/cat", 0);

	follow_symlinks = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
	inotify_workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;

	open_max = read_open_max();
	if (getenv("EV_TRACE") != NULL)
		fprintf(stderr, "open_max: %d\n", open_max);

	install_handlers();

	if (opt_status)
		start_status_filter();

	notify_init();

	if (inotify_workaround)
		warnx("broken inotify workaround enabled");

	if (isatty(STDIN_FILENO))
		usage(0);

	atexit(cleanup);

	n = process_input(stdin, open_max);
	if (n == 0)
		errx(1, "No regular files to watch");
	if (n == -1)
		errx(1, "Too many files listed; the hard limit for your login "
		    "class is %d. Please consult "
		    "http://eradman.com/entrproject/limits.html", open_max);

	for (i = 0; i < n_files; i++)
		watch_file(files[i]);

	if (!opt_noninteractive)
		tty_setup();

	watch_loop(argv);
	return 0;
}
